/**
 * @name Unsafe archive extraction
 * @description Extracting archives without validating paths can lead to arbitrary file write (Zip Slip)
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-archive-extraction
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeArchiveConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // zipfile.ZipFile methods
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["namelist", "infolist", "getinfo"]).getACall() and
      source = call
      or
      // tarfile.TarFile methods  
      call = API::moduleImport("tarfile").getMember(["open", "TarFile"]).getReturn().getMember(["getmembers", "getmember", "getnames"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // zipfile extract operations
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["extract", "extractall"]).getACall() and
      sink = call.getArg(0)
      or
      // tarfile extract operations
      call = API::moduleImport("tarfile").getMember(["open", "TarFile"]).getReturn().getMember(["extract", "extractall"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeArchiveFlow = TaintTracking::Global<UnsafeArchiveConfig>;
import UnsafeArchiveFlow::PathGraph

from UnsafeArchiveFlow::PathNode source, UnsafeArchiveFlow::PathNode sink
where UnsafeArchiveFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe archive extraction from $@.", source.getNode(), "archive member"
